function fixture = legacyNominalFixture()
%legacyNominalFixture Frozen nominal inputs and measured regression references.
% Captured from the unchanged production pipeline on 2026-09-10 using
% MATLAB R2025b Update 4. Independent of scenarioParameters/scenario1Path.
% Reconstruct with cubicPath, timeScale, pathToInputs and simulateKinematics.
% Expected outputs are measured constants, never regenerated by this fixture.

    fixture.vehicle.length = 4.50;
    fixture.vehicle.width = 1.80;
    fixture.vehicle.wheelbase = 2.70;
    fixture.vehicle.rearOverhang = 0.90;
    fixture.vehicle.frontOverhang = 0.90;
    fixture.vehicle.maxSteering = deg2rad(35);
    fixture.vehicle.minTurningRadius = 2.70/tan(deg2rad(35));

    fixture.scenario.name = 'Standard Parking';
    fixture.scenario.spaceLength = 6.50;
    fixture.scenario.rearCarPose = [0; 0; 0];
    fixture.scenario.frontCarPose = [11; 0; 0];
    fixture.scenario.initialPose = [11.76; 2.80; 0];
    fixture.scenario.targetPose = [5.50; 0; 0];
    fixture.midPose = [8.63; 1.40; deg2rad(48.19)];
    fixture.ks = 3.59;
    fixture.ke = 3.59;
    fixture.nSamples = 201;
    fixture.direction = [-1, -1];
    fixture.duration = [7.0, 7.0];
    fixture.dt = 0.05;

    fixture.expected.finalPositionError = 0.00039528205562471008;
    fixture.expected.finalHeadingError = 2.9070170749767588e-15;
    fixture.expected.maxTimeMatchedXYError = 0.022112765719869493;
    % Legacy sample RMSE over 281 samples, with the shared join counted once.
    % This is not the time-weighted RMSE proposed for later production work.
    fixture.expected.xyRMSE = 0.017227084466788004;
    fixture.expected.maxSteering = 0.57240667692870151;

    % Frozen shape/state checkpoints catch changes hidden by scalar summaries.
    fixture.expected.referenceMidPoses = [ ...
        10.045414828378961, 7.2145851716210387; ...
        2.4344801458397596, 0.36551985416024019; ...
        0.42061957197361854, 0.42061957197361854];
    fixture.expected.checkpointTimes = [3.5, 7.0, 10.5, 14.0];
    fixture.expected.simulatedPoses = [ ...
        10.061200358186285, 8.6250713625637143, 7.2303584052597705, 5.5002737423393375; ...
        2.4481981868850302, 1.4114693726595591, 0.37967510141391725, 0.00028515440581010907; ...
        0.41611726225585655, 0.84103085885845374, 0.42507854467575457, 2.662421064864029e-15];

    % Absolute tolerances: comfortably above roundoff but below meaningful
    % changes to the legacy Euler/interpolation behavior. Not quality gates.
    fixture.tolerance.position = 1e-8;       % m; also position-error metrics
    fixture.tolerance.heading = 1e-10;      % rad
    fixture.tolerance.steering = 1e-8;      % rad; baseline comparison only
    fixture.tolerance.configuration = 1e-12; % fixed parameters/time/endpoints
end
